import{_ as a,o,c as t,a2 as i}from"./chunks/framework.DCVnL8g5.js";const m=JSON.parse('{"title":"Buenas prácticas","description":"","frontmatter":{},"headers":[],"relativePath":"data-engineering/delta-lake/08-buenas-practicas.md","filePath":"data-engineering/delta-lake/08-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"data-engineering/delta-lake/08-buenas-practicas.md"};function s(r,e,l,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h1><p>Cierra el recorrido: <code>/data/events</code> como lago versionado, <code>/data/customers</code> actualizado con MERGE, streams con checkpoint propio. Las decisiones de abajo son operativas; no son un checklist de producto Databricks.</p><p>Documentación: <a href="https://docs.delta.io/" target="_blank" rel="noreferrer">docs.delta.io</a>, <a href="https://docs.delta.io/latest/optimizations-oss.html" target="_blank" rel="noreferrer">optimizaciones</a>, <a href="https://docs.delta.io/latest/delta-utility.html" target="_blank" rel="noreferrer">utilidades</a>, <a href="https://docs.delta.io/latest/delta-kernel.html" target="_blank" rel="noreferrer">Delta Kernel</a>.</p><h2 id="diseno" tabindex="-1">Diseño <a class="header-anchor" href="#diseno" aria-label="Permalink to &quot;Diseño&quot;">​</a></h2><ul><li>Esquema <strong>explícito</strong> en ingestión (sobre todo streaming). Enforcement por defecto; evolución con <code>ALTER TABLE</code> o <code>WITH SCHEMA EVOLUTION</code> / <code>withSchemaEvolution()</code> <strong>cuando</strong> el contrato lo permite. No dejes <code>mergeSchema=true</code> en todos los writes.</li><li>Particiona solo si el predicado estable y el volumen por partición lo justifican. Evita high-cardinality (<code>user_id</code>, ids de evento).</li><li>Delta Lake <strong>no</strong> es Medallion. Si usas bronze/silver/gold, es un patrón de <em>pipelines</em>, no una obligación del formato.</li><li>Spark es el motor de este manual. Flink, Trino, Presto, Hive, Athena o un conector <strong>Kernel</strong> pueden leer/escribir Delta; el soporte de OPTIMIZE, CDF, deletion vectors o clustering <strong>no</strong> es idéntico. Comprueba el conector.</li></ul><h2 id="escrituras" tabindex="-1">Escrituras <a class="header-anchor" href="#escrituras" aria-label="Permalink to &quot;Escrituras&quot;">​</a></h2><ul><li>Evita tiny files: no hagas un append de 40 filas cada segundo sin compactar después. Agrupa micro-batches o programa <code>OPTIMIZE</code> en particiones calientes.</li><li><code>overwrite</code> es un snapshot nuevo, no un update. El historial queda; el actual no.</li><li><code>MERGE</code> con predicados que acoten ficheros (y particiones). Deduplica el source. No prometas que el merge es barato.</li><li>Varios writers: entiende conflictos (capítulo 3). No lances dos streams con el mismo checkpoint.</li></ul><h2 id="operacion" tabindex="-1">Operación <a class="header-anchor" href="#operacion" aria-label="Permalink to &quot;Operación&quot;">​</a></h2><ul><li>Compaction OSS: <code>OPTIMIZE</code> / <code>executeCompaction()</code>. Z-Order solo en columnas de filtro real, con stats.</li><li><code>VACUUM</code> con retención <strong>segura</strong> (default 7 días de data files). <code>DRY RUN</code> antes en tablas grandes. No uses <code>RETAIN 0 HOURS</code> fuera de un lab marcado como destructivo.</li><li>Observa <code>DESCRIBE DETAIL</code> (ficheros, tamaño, protocol) e <code>HISTORY</code> (qué operaciones hinchan el log).</li><li>Storage: S3, ADLS, GCS, HDFS. Configura el filesystem/Hadoop según la guía <strong>actual</strong> de Delta; no copies LogStore de 2019 sin verificar si tu release aún lo necesita.</li></ul><h2 id="evolucion" tabindex="-1">Evolución <a class="header-anchor" href="#evolucion" aria-label="Permalink to &quot;Evolución&quot;">​</a></h2><ul><li>Añadir columnas es barato y explícito. Renombrar/quitar/cambiar tipo suele exigir <code>overwriteSchema</code> o table features (column mapping) que <strong>suben</strong> el protocolo.</li><li>CDF, deletion vectors, clustering, identity columns: actívalos porque un lector/writer los necesita, no por moda. Un reader antiguo dejará de abrir la tabla.</li><li>Distingue <strong>Delta Lake OSS</strong> de Databricks Runtime, Unity Catalog (producto), Predictive Optimization y Auto Optimize gestionado.</li></ul><h2 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h2><ul><li><code>checkpointLocation</code> persistente, no un <code>/tmp</code> del driver. Distinto de <code>_delta_log</code>.</li><li>Exactly-once del <strong>sink Delta</strong> ≠ exactly-once de todo el sistema.</li><li>Source append-only: <code>skipChangeCommits</code> si la fuente recibe DML y no te importan esos commits; CDF si sí te importan los cambios de fila.</li><li><code>foreachBatch</code> + MERGE: idempotencia (<code>txnAppId</code>/<code>txnVersion</code> o merge por clave estable). Sin side effects sueltos.</li></ul><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><ul><li>Time travel y <code>RESTORE</code> ayudan a <strong>inspeccionar y revertir</strong> dentro de la retención. No sustituyen backups (otro bucket, replicación, export).</li><li>Si el log o los Parquet desaparecen del prefix, no hay snapshot que consultar.</li><li>No edites <code>_delta_log</code> para “recuperar”. Restaura una copia o un <code>RESTORE</code> a una versión que aún tenga ficheros.</li></ul><h2 id="recorrido-del-manual" tabindex="-1">Recorrido del manual <a class="header-anchor" href="#recorrido-del-manual" aria-label="Permalink to &quot;Recorrido del manual&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Parquet + _delta_log</span></span>
<span class="line"><span>  → tabla events</span></span>
<span class="line"><span>  → commits / snapshots</span></span>
<span class="line"><span>  → MERGE customers</span></span>
<span class="line"><span>  → VERSION AS OF / VACUUM</span></span>
<span class="line"><span>  → OPTIMIZE / particiones</span></span>
<span class="line"><span>  → readStream / writeStream</span></span>
<span class="line"><span>  → operación</span></span></code></pre></div><p>Iceberg se documenta aparte: mismo tipo de problema (tabla lakehouse), otro protocolo. No mezcles recetas.</p>`,18)])])}const h=a(n,[["render",s]]);export{m as __pageData,h as default};
